Function Solvable(u);
Begin
    If u là định kết thúc then {Solvable(u) ← true; stop }
    If u không là định kết thúc và không có định kè then {Solvable(u) ← false; stop }
    For mỗi toán tử R áp dụng được tại u do
        { Ok ← true;
            For mỗi v kể u theo R do
                If Solvable(v) = false then {Ok ← false; exit }
    If Ok then Solvable(u) ← true; Operator(u) ← R; stop}
Solvable(u) ← false;
End;
