Procedure Simulated_Anneaning;
Begin
    t ← 0;
    u ← trạng thái ban đầu nào đó;
    T ← nhiệt độ ban đầu;
    repeat
        v ← trạng thái được chọn ngẫu nhiên trong
        lân cận u;
        if cost(v) > cost(u) then u ← v;
        else u ← v với xác suất e^Δ/T;
        T ← g(T,t);
        t ← t + 1;
    until T đủ nhỏ;
End;
Chú ý:
    g(T,t) thỏa mãn
    điều kiện
        g(T,t) < T
    với mọi t.
    Hàm này xác
    định tốc độ giảm
    nhiệt độ.
